export function computeInvoice(input) {
  const { lines, discountKobo = 0 } = input ?? {};

  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }

  if (!Number.isInteger(discountKobo) || discountKobo < 0) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  // Keep all monetary arithmetic exact, including intermediate products.
  let subtotal = 0n;
  const items = [];

  for (let index = 0; index < lines.length; index++) {
    const { sku, unitPriceKobo, qty, vatExempt } = lines[index] ?? {};

    if (!Number.isInteger(unitPriceKobo) || unitPriceKobo < 0) {
      throw new RangeError(
        `lines[${index}].unitPriceKobo must be a non-negative integer`
      );
    }

    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError(`lines[${index}].qty must be a positive integer`);
    }

    const lineSubtotal = BigInt(unitPriceKobo) * BigInt(qty);
    subtotal += lineSubtotal;

    items.push({
      sku,
      vatExempt,
      index,
      subtotal: lineSubtotal,
      discount: 0n,
      remainder: 0n
    });
  }

  const requestedDiscount = BigInt(discountKobo);
  const appliedDiscount =
    requestedDiscount < subtotal ? requestedDiscount : subtotal;

  if (subtotal > 0n && appliedDiscount > 0n) {
    let allocated = 0n;

    for (const item of items) {
      const numerator = appliedDiscount * item.subtotal;
      item.discount = numerator / subtotal;
      item.remainder = numerator % subtotal;
      allocated += item.discount;
    }

    let leftover = appliedDiscount - allocated;

    if (leftover > 0n) {
      const ranked = items.slice().sort((a, b) => {
        if (a.remainder !== b.remainder) {
          return a.remainder > b.remainder ? -1 : 1;
        }
        return a.index - b.index;
      });

      for (let index = 0; leftover > 0n; index++) {
        ranked[index].discount += 1n;
        leftover -= 1n;
      }
    }
  }

  let invoiceVat = 0n;
  const resultLines = items.map((item) => {
    const net = item.subtotal - item.discount;

    // 7.5% = 3/40; adding half the denominator gives half-up rounding.
    const vat =
      item.vatExempt === false ? (net * 3n + 20n) / 40n : 0n;

    invoiceVat += vat;

    return {
      sku: item.sku,
      subtotalKobo: Number(item.subtotal),
      discountKobo: Number(item.discount),
      netKobo: Number(net),
      vatKobo: Number(vat)
    };
  });

  return {
    subtotalKobo: Number(subtotal),
    discountKobo: Number(appliedDiscount),
    vatKobo: Number(invoiceVat),
    totalKobo: Number(subtotal - appliedDiscount + invoiceVat),
    lines: resultLines
  };
}
